#!/usr/bin/env python3
# Some portions generated by Codex. Whole-lifetime V8 main-isolate client samples, not exact CPU or POST-only attribution.
import pathlib,json,collections,hashlib,sys
p=pathlib.Path(sys.argv[1]);leaves=collections.Counter();weights=collections.Counter();stacks=collections.Counter();manifests=[];total=0;lineTicks=collections.Counter()
for f in sorted(p.glob('query-*.cpuprofile')):
 x=json.loads(f.read_text());nodes={n['id']:n for n in x['nodes']};
 for n in x['nodes']:
  if n['callFrame'].get('url','').endswith('/client.mjs'):
   for tick in n.get('positionTicks',[]):lineTicks[str(tick['line'])]+=tick['ticks']
 parents={child:n['id'] for n in x['nodes'] for child in n.get('children',[])}
 def name(i):
  c=nodes[i]['callFrame'];return c.get('functionName','')+' @ '+c.get('url','')+':'+str(c.get('lineNumber',-1)+1)
 samples=x.get('samples',[]);deltas=x.get('timeDeltas',[]);assert len(samples)==len(deltas)
 for i,dt in zip(samples,deltas):
  k=name(i);leaves[k]+=1;weights[k]+=dt;total+=1;chain=[]
  for j in range(12):
   chain.append(name(i))
   if i not in parents:break
   i=parents[i]
  stacks[' <- '.join(chain)]+=1
 manifests.append({'file':f.name,'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'samples':len(samples),'timeDeltaSumMicros':sum(deltas),'profileSpanMicros':x['endTime']-x['startTime']})
print(json.dumps({'scope':'One fresh Node process per recorded diagnostic request. V8 main-isolate samples span startup, session GET, metrics, HTTP receive, JSON parsing and counting; native worker CPU including gzip decompression is not comprehensively sampled. Sampled leaf time is not exact process CPU or POST-only timing. JFR covers a different process. Idle/runtime frames retained.','profiles':manifests,'samples':total,'clientSourceLineTicks':dict(lineTicks),'leafCounts':leaves.most_common(50),'leafSampledMicros':weights.most_common(50),'topStacks':stacks.most_common(35)},indent=2))
